 for r,c in pts:
  boundary=(r==0 or r==29 or c==0 or c==29 or any(not(0<=nr<30 and 0<=nc<30) or G[nr,nc]==3 for nr,nc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1))))
  if boundary:dists[r,c]=0;q.append((r,c))
 while q:
